from itertools import product

def expand(matrix):
    keys = [k for k in matrix if k not in ('include', 'exclude')]
    combos = [dict(zip(keys, values)) for values in product(*(matrix[k] for k in keys))]
    for ex in matrix.get('exclude', []):
        combos = [c for c in combos if not all(c.get(k) == v for k, v in ex.items())]
    for inc in matrix.get('include', []):
        matched = False
        if keys:
            original = {k: v for k, v in inc.items() if k in keys}
            extra = {k: v for k, v in inc.items() if k not in keys}
            if original and extra:
                for c in combos:
                    if all(c.get(k) == v for k, v in original.items()):
                        c.update(extra)
                        matched = True
        if not matched:
            combos.append(dict(inc))
    return combos

