function filesForShard(files, shardIndex, shardTotal) {
  if (!Number.isInteger(shardIndex) || shardIndex < 1 || shardIndex > shardTotal) {
    throw new Error('shardIndex out of range');
  }
  return [...files].sort().filter((_, i) => i % shardTotal === shardIndex - 1);
}
